/*! Sortable minimal local bundle */
(function(global){
  function Sortable(el, opts){
    opts = opts || {};
    var dragEl = null;
    el.querySelectorAll('[data-id]').forEach(function(item){
      item.draggable = true;
      item.addEventListener('dragstart', function(e){ dragEl = item; e.dataTransfer.effectAllowed='move'; });
      item.addEventListener('dragover', function(e){ e.preventDefault(); });
      item.addEventListener('drop', function(e){
        e.preventDefault();
        if (!dragEl || dragEl===item) return;
        var rect = item.getBoundingClientRect();
        var next = (e.clientY - rect.top) / (rect.bottom-rect.top) > 0.5;
        el.insertBefore(dragEl, next ? item.nextSibling : item);
        if (opts.onEnd) opts.onEnd();
      });
    });
  }
  Sortable.create = function(el, opts){ return new Sortable(el, opts); };
  global.Sortable = Sortable;
})(window);
